+html,body{width:100%;height:100%;background:var(--bg);color:#e8e8e8;font-family:"Segoe UI",Roboto,Helvetica,Arial,sans-serif;overflow:hidden;user-select:none}
+#wrap{position:fixed;inset:0;display:flex;flex-direction:column}
+#gamebar{display:flex;align-items:center;gap:10px;padding:6px 12px;background:#10151c;border-bottom:1px solid #232c38;font-size:12px;letter-spacing:.08em}
+#gamebar b{color:var(--amber)} #gamebar .sp{flex:1}
+button{font-family:inherit}
+.screen{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;background:radial-gradient(ellipse at 50% 30%,#1a2230 0%,#0b0e12 70%);z-index:20;padding:20px;text-align:center}
+.screen.hidden{display:none}
+.card{max-width:640px;width:min(92vw,640px);background:rgba(16,21,28,.94);border:1px solid #2b3648;border-radius:10px;padding:26px 28px;text-align:left;box-shadow:0 20px 60px rgba(0,0,0,.6)}
+.card h1{font-size:30px;letter-spacing:.12em;color:#fff} .card h1 span{color:var(--amber)}
+.card h2{font-size:18px;letter-spacing:.1em;color:var(--amber);margin-bottom:8px}
+.card p{font-size:14px;line-height:1.55;color:#c6cfdb;margin:8px 0}
+.btn{display:inline-block;background:var(--amber);color:#111;border:none;border-radius:5px;padding:12px 26px;font-weight:700;letter-spacing:.1em;font-size:14px;cursor:pointer;margin:6px 6px 0 0}
+.btn.ghost{background:transparent;color:#dfe6ef;border:1px solid #43536a}
+.btn:disabled{opacity:.4;cursor:not-allowed}
+.row{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
+.kbd{background:#222c3a;border:1px solid #46566d;border-bottom-width:3px;border-radius:4px;padding:1px 7px;font-size:12px;font-family:monospace}
+#stage{position:relative;flex:1;overflow:hidden;background:#000}
+canvas#view{position:absolute;inset:0;width:100%;height:100%;display:block;cursor:crosshair}
+/* HUD */
+#hud{position:absolute;inset:0;pointer-events:none;font-size:calc(13px * var(--hud-scale));z-index:5}
+#compass{position:absolute;top:8px;left:50%;transform:translateX(-50%);width:min(420px,60vw);height:30px;background:linear-gradient(180deg,rgba(0,0,0,.55),rgba(0,0,0,.25));border:1px solid rgba(255,255,255,.15);border-radius:4px;overflow:hidden}
+#compasstrip{position:absolute;top:0;height:100%;white-space:nowrap;font-family:monospace;font-size:13px;line-height:30px;color:#cfd6e2}
+#compasstrip .deg{color:var(--amber);font-weight:700}
+#objstar{color:var(--amber);font-weight:900}
+#missiontrack{position:absolute;top:46px;left:12px;background:rgba(0,0,0,.5);border-left:3px solid var(--amber);padding:6px 10px;border-radius:0 5px 5px 0;max-width:300px}
+#missiontrack .t{font-size:11px;letter-spacing:.12em;color:var(--amber)} #missiontrack .o{font-size:13px;color:#fff}
+#minimap{position:absolute;top:46px;right:12px;width:150px;height:150px;background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.2);border-radius:50%;overflow:hidden}
+#feed{position:absolute;top:204px;right:12px;width:230px;display:flex;flex-direction:column;gap:4px;align-items:flex-end}
+#feed div{background:rgba(0,0,0,.55);padding:3px 8px;border-radius:4px;font-size:12px}
+#bottomleft{position:absolute;left:12px;bottom:12px;background:rgba(0,0,0,.5);border:1px solid rgba(255,255,255,.12);border-radius:6px;padding:8px 12px}
+#healthbar{width:190px;height:10px;background:#2a1214;border-radius:5px;overflow:hidden;margin-top:5px}
+#healthfill{height:100%;width:100%;background:linear-gradient(90deg,#57d977,#a8e05f);transition:width .15s}
+#bottomright{position:absolute;right:12px;bottom:12px;text-align:right;background:rgba(0,0,0,.5);border:1px solid rgba(255,255,255,.12);border-radius:6px;padding:8px 12px}
+#ammo{font-size:26px;font-weight:800;font-family:monospace} #ammo small{font-size:13px;color:#9fb0c5}
+#wname{font-size:11px;letter-spacing:.14em;color:var(--amber)}
+#streaks{margin-top:4px;font-size:12px;color:#cfe3ff}
+#cross{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:44px;height:44px}
+#hitmark{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) rotate(45deg);width:30px;height:30px;opacity:0}
