+#hitmark:before{left:13px;top:0;width:4px;height:30px} #hitmark:after{top:13px;left:0;height:4px;width:30px}
+#hitmark.kill:before,#hitmark.kill:after{background:var(--red)}
+#dmgvin{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 45%,rgba(200,0,0,.55) 100%);opacity:0;transition:opacity .2s}
