const puppeteer = require('puppeteer-core');
const SHOT = '/tmp/sp_shots';
(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--window-size=1280,720', '--hide-scrollbars']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 720 });
  const errs = [];
  page.on('pageerror', e => errs.push('PAGEERROR: ' + e.message));
  await page.goto('file:///Users/runner/work/PlayGround/PlayGround/game/index.html', { waitUntil: 'load' });
  await new Promise(r => setTimeout(r, 600));
  await page.evaluate(() => document.getElementById('btnDeploy').click());
  await page.waitForFunction(() => window.__SP && window.__SP.G.mode === 'play', { timeout: 5000 });
  await new Promise(r => setTimeout(r, 500));
  // Gun-kill path: find LOS enemy, close to 4m with LOS, ADS fire until kill
  const gun = await page.evaluate(() => {
    const SP = window.__SP, G = SP.G;
    let tgt = null;
    for (const e of G.enemies) { if (!e.dead && SP.los(G.px, G.py, e.x, e.y)) { tgt = e; break; } }
    if (!tgt) return { ok: false, why: 'no LOS enemy' };
    // step player toward enemy until 4m, keeping LOS (straight line, walls may block; try lateral offsets)
    const cand = [];
    for (let t = 0.2; t < 0.95; t += 0.05) cand.push([G.px + (tgt.x - G.px) * t, G.py + (tgt.y - G.py) * t]);
    let placed = false;
    for (const [cx, cy] of cand) {
      const gx = Math.floor(cx), gy = Math.floor(cy);
      if (G.map.g[gy] && G.map.g[gy][gx] === 0 && SP.los(cx, cy, tgt.x, tgt.y) && Math.hypot(tgt.x - cx, tgt.y - cy) <= 5) {
        G.px = cx; G.py = cy; placed = true; break;
      }
    }
    if (!placed) return { ok: false, why: 'no LOS perch' };
    G.pa = Math.atan2(tgt.y - G.py, tgt.x - G.px);
    G.ads = true;
    return { ok: true, d: Math.hypot(tgt.x - G.px, tgt.y - G.py).toFixed(2), hp0: tgt.hp };
  });
  await page.evaluate(() => { window.__SP.G.firing = true; });
  await new Promise(r => setTimeout(r, 4000));
  await page.evaluate(() => { window.__SP.G.firing = false; window.__SP.G.ads = false; });
  const gunAfter = await page.evaluate(() => ({ kills: window.__SP.G.kills, score: window.__SP.G.score }));
  await page.screenshot({ path: SHOT + '/8_gunkill.png' });
  // Win path via real killEnemy on all remaining (mission 1 target 8)
  const win = await page.evaluate(() => {
    const SP = window.__SP, G = SP.G;
    for (const e of [...G.enemies]) if (!e.dead) SP.killEnemy(e);
    return { mode: G.mode, kills: G.kills };
  });
  await new Promise(r => setTimeout(r, 600));
  await page.screenshot({ path: SHOT + '/9_win.png' });
  const endVisible = await page.evaluate(() => !document.getElementById('scrEnd').classList.contains('hidden') && document.getElementById('endTitle').textContent);
  // Next mission button -> mission 2
  await page.evaluate(() => document.getElementById('btnNext').click());
  await new Promise(r => setTimeout(r, 800));
  const m2 = await page.evaluate(() => ({ mode: window.__SP.G.mode, mi: window.__SP.G.mi, intel: window.__SP.G.map.items.filter(i => !i.taken).length }));
  await page.screenshot({ path: SHOT + '/10_mission2.png' });
  // Fail path: lethal damage
  await page.evaluate(() => window.__SP.hurtPlayer(9999, window.__SP.G.px + 1, window.__SP.G.py));
  await new Promise(r => setTimeout(r, 500));
  const failTitle = await page.evaluate(() => document.getElementById('endTitle').textContent);
  await page.screenshot({ path: SHOT + '/11_fail.png' });
  // Persistence: reload, check XP/best banked
  await page.reload({ waitUntil: 'load' });
  await new Promise(r => setTimeout(r, 600));
  const saved = await page.evaluate(() => ({ rank: document.getElementById('ranklabel').textContent, best: document.getElementById('bestline').textContent }));
  console.log(JSON.stringify({ gun, gunAfter, win, endVisible, m2, failTitle, saved, errs }));
  await browser.close();
})().catch(e => { console.error('DRIVER_FAIL ' + e.message); process.exit(1); });

