<div class="screen hidden" id="scrEnd"><div class="card"><h2 id="endKick">DEBRIEF</h2><h1 id="endTitle">MISSION COMPLETE</h1><p id="endBody"></p><p id="endStats" style="font-family:monospace"></p><div class="row"><button class="btn" id="btnNext">NEXT MISSION ▶</button><button class="btn ghost" id="btnRetry">RETRY</button><button class="btn ghost" id="btnBrief">BRIEFING</button></div></div></div>
</div>
</div>
<script>
"use strict";
/* ============ STRIKE PROTOCOL — original CoD-fidelity browser FPS ============ */
/* Error surface */
const errBox=document.getElementById('err');
window.addEventListener('error',e=>{errBox.style.display='block';errBox.textContent='Recovered from error: '+(e.message||'unknown')+' — press P to pause, or Abort to briefing. Progress is autosaved.';});
/* ---------- persistence ---------- */
const SAVE_KEY='strike_protocol_save_v1';
let save={xp:0,rank:1,best:0,completed:0,unlocks:{smg:true,dmr:false}};
try{const s=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if(s&&typeof s==='object')save=Object.assign(save,s);}catch(e){}
function persist(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(save));}catch(e){}}
function rankFromXP(x){return 1+Math.floor(x/1500);}
function refreshRank(){save.rank=rankFromXP(save.xp);save.unlocks.dmr=save.rank>=2||save.completed>=1;
document.getElementById('ranklabel').textContent='RANK '+save.rank+' · '+save.xp+' XP';
document.getElementById('bestline').textContent='RANK '+save.rank+' · '+save.xp+' XP · BEST SCORE '+save.best+' · CAMPAIGN COMPLETED x'+save.completed+' · DMR '+(save.unlocks.dmr?'UNLOCKED':'unlocks at Rank 2');
document.getElementById('xpfill').style.width=Math.min(100,(save.xp%1500)/15)+'%';}
refreshRank();
/* ---------- settings ---------- */
const set={sens:1.4,cb:false,sub:true,mute:false,reduceFlash:false};
try{Object.assign(set,JSON.parse(localStorage.getItem('sp_set')||'{}'));}catch(e){}
const $=id=>document.getElementById(id);
$('setSens').value=set.sens;$('setCB').checked=set.cb;$('setSub').checked=set.sub;$('setMute').checked=set.mute;$('setFlash').checked=set.reduceFlash;
function bindSet(id,key,fn){$(id).addEventListener('change',e=>{set[key]=e.target.type==='checkbox'?e.target.checked:parseFloat(e.target.value);try{localStorage.setItem('sp_set',JSON.stringify(set));}catch(x){} if(fn)fn();});}
bindSet('setSens','sens');bindSet('setCB','cb',applyCB);bindSet('setSub','sub');bindSet('setMute','mute');bindSet('setFlash','reduceFlash');
function applyCB(){document.documentElement.style.setProperty('--amber',set.cb?'#00e5ff':'#e8b64c');document.documentElement.style.setProperty('--green',set.cb?'#00e5ff':'#7dff9a');}
/* ---------- audio (all synthesized) ---------- */
let AC=null;function ac(){if(AC)return AC;try{AC=new (window.AudioContext||window.webkitAudioContext)();}catch(e){}return AC;}
function beep(f,d,type,g,slide){if(set.mute)return;const c=ac();if(!c)return;try{const o=c.createOscillator(),v=c.createGain();o.type=type||'square';o.frequency.value=f;if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(30,slide),c.currentTime+d);v.gain.value=g||.12;v.gain.exponentialRampToValueAtTime(.001,c.currentTime+d);o.connect(v);v.connect(c.destination);o.start();o.stop(c.currentTime+d);}catch(e){}}
function noise(dur,g,low){if(set.mute)return;const c=ac();if(!c)return;try{const n=c.sampleRate*dur,b=c.createBuffer(1,n,c.sampleRate),ch=b.getChannelData(0);for(let i=0;i<n;i++)ch[i]=(Math.random()*2-1)*(1-i/n);const s=c.createBufferSource();s.buffer=b;const f=c.createBiquadFilter();f.type='lowpass';f.frequency.value=low||1200;const v=c.createGain();v.gain.value=g||.25;s.connect(f);f.connect(v);v.connect(c.destination);s.start();}catch(e){}}
const SFX={shot(w){noise(.12,w===2?.4:.22,w===2?900:2600);beep(w===2?120:220,.08,'sawtooth',.08,60);},dry(){beep(1200,.05,'square',.06);},reload(){beep(500,.07,'square',.08);setTimeout(()=>beep(700,.07,'square',.08),120);},hit(){beep(900,.06,'square',.1,1400);},kill(){beep(300,.25,'sawtooth',.12,90);noise(.2,.2,800);},hurt(){noise(.25,.3,400);beep(90,.3,'sine',.2,50);},boom(){noise(.9,.5,300);beep(55,.8,'sine',.3,28);},pick(){beep(660,.1,'sine',.12,990);},obj(){beep(523,.12,'sine',.14);setTimeout(()=>beep(784,.18,'sine',.14),130);},click(){beep(440,.05,'square',.06);},heart(){beep(55,.12,'sine',.25,40);}};
/* ---------- maps & missions ---------- */
const MAPS=[
["####################","#........##........#","#........##...i....#","#..P.....##........#","#........##........#","#...######..####..#","#...#..........#..#","#...#..####..#..#.#","#......#.....#....#","####...#..i..#.####","#......#.....#....#","#..##..####....#..#","#..#..........##..#","#..#..######......#","#..................#","#....i.....##......#","#........##......X#","####################"],
["####################","#..i.....##........#","#........##....##..#","#..####..##....##.#","#..#.............#","#..#.######..#...#","#....#....#..#.#.#","#....#....#..#...#","#.P..#....#..###.#","#....#....#......#","#....######..##..#","#............##.i#","#.######..#####..#","#.#.....i.....#..#","#.#..######..#..X#","#.................#","#..................#","####################"],
["####################","#..................#","#.P....####....i...#","#......####........#","#..##..####..###..#","#..##........###..#","#......####........#","#......####...##..#","#..i...####...##..#","#......####........#","####.#####..####..#","#......####.....i.#","#..##..####..###..#","#..##........##...#","#.......i......X..#","#..................#","#..................#","####################"]];
function parseMap(rows){const g=[];let spawn={x:2.5,y:3.5},exfil={x:17,y:16},items=[];for(let y=0;y<rows.length;y++){g[y]=[];for(let x=0;x<rows[y].length;x++){const c=rows[y][x];g[y][x]=(c==='#')?1:0;if(c==='P'){spawn={x:x+.5,y:y+.5};}if(c==='X')exfil={x:x+.5,y:y+.5};if(c==='i')items.push({x:x+.5,y:y+.5,taken:false});}}return {g,spawn,exfil,items,w:rows[0].length,h:rows.length};}
const WEAPONS=[
{id:0,name:'MK-7 ASSAULT RIFLE [1]',mag:30,res:120,dmg:34,rpm:540,spread:.028,adsSpread:.008,reload:1.6,auto:true,range:14,kick:.011,zoom:1.25},
{id:1,name:'VK-9 SMG [2]',mag:40,res:160,dmg:22,rpm:800,spread:.05,adsSpread:.02,reload:1.4,auto:true,range:10,kick:.008,zoom:1.12},
{id:2,name:'LR-12 DMR [3]',mag:8,res:40,dmg:120,rpm:70,spread:.012,adsSpread:.001,reload:2.2,auto:false,range:22,kick:.035,zoom:2.2,locked:true}];
const MISSIONS=[{name:'MISSION 1/3 — STREET SWEEP',brief:'Eliminate 8 hostiles patrolling the district.',killTarget:8,enemies:8,eType:[0,0,0,1,0,1,0,0],intel:0,waves:1},
{name:'MISSION 2/3 — INTEL RECOVERY',brief:'Collect 3 intel cases, then reach the EXFIL star.',killTarget:0,enemies:9,eType:[0,1,0,1,2,0,1,0,1],intel:3,waves:1},
{name:'MISSION 3/3 — LAST STAND',brief:'Survive 3 waves. Streaks online: UAV (U) + Airstrike (T).',killTarget:14,enemies:6,eType:[0,1,0,1,2,0],intel:0,waves:3}];
/* ---------- state ---------- */
const cv=$('view'),ctx=cv.getContext('2d');
const mm=$('minimap'),mmc=mm.getContext('2d');
let W=960,H=540;
function fit(){const r=$('stage').getBoundingClientRect();W=Math.max(480,Math.floor(r.width));H=Math.max(320,Math.floor(r.height));cv.width=W;cv.height=H;}
window.addEventListener('resize',fit);
const G={mode:'brief',mi:0,endless:false,map:null,px:0,py:0,pa:0,hp:100,lastHurt:-9,alive:true,kills:0,score:0,intel:0,frags:2,uav:0,strike:0,uavT:0,killStreak:0,t:0,wi:0,weapons:null,firing:false,ads:false,triggerT:0,reloadT:0,spreadB:0,enemies:[],tracers:[],parts:[],nades:[],strikes:[],msgs:[],objDone:false,exfilOn:false,subT:0,sprint:false,crouch:false,lockHint:true,wave:1,waveSpawned:0,killTarget:8,shake:0,started:0};
function newLoadout(){return WEAPONS.map(w=>({cfg:w,mag:w.mag,res:w.res}));}
function startMission(mi,endless){fit();const M=MISSIONS[mi];G.mode='play';G.mi=mi;G.endless=!!endless;G.map=parseMap(MAPS[endless?0:mi]);G.px=G.map.spawn.x;G.py=G.map.spawn.y;G.pa=0;G.hp=100;G.alive=true;G.kills=0;G.score=0;G.intel=0;G.frags=2;G.uav=endless?1:(mi===2?1:0);G.strike=endless?1:(mi===2?1:0);G.uavT=0;G.killStreak=0;G.wi=0;G.weapons=newLoadout();G.enemies=[];G.tracers=[];G.parts=[];G.nades=[];G.strikes=[];G.t=0;G.firing=false;G.ads=false;G.reloadT=0;G.spreadB=0;G.objDone=false;G.exfilOn=(M.killTarget===0&&M.intel===0);G.wave=1;G.waveSpawned=0;G.killTarget=endless?9999:(M.killTarget||9999);G.started=performance.now();G.shake=0;
 if(endless){G.killTarget=9999;}
 spawnWave(M.enemies,M.eType);
 $('scrBrief').classList.add('hidden');$('scrPause').classList.add('hidden');$('scrEnd').classList.add('hidden');
 say('HQ','Mission started. '+M.brief);toast(M.name);updateTrack();SFX.obj();
 if('ontouchstart'in window)$('touch').style.display='block';}
function randFree(){const m=G.map;for(let k=0;k<80;k++){const x=1+Math.random()*(m.w-2),y=1+Math.random()*(m.h-2);if(m.g[Math.floor(y)][Math.floor(x)]===0&&dist(x,y,G.px,G.py)>5)return{x,y};}return{x:G.map.w-3,y:G.map.h-3};}
function spawnWave(n,types){for(let i=0;i<n;i++){const p=randFree();const ty=(types&&types[i%types.length])||0;const hp=ty===2?60:(ty===1?80:110);G.enemies.push({x:p.x,y:p.y,hp,maxhp:hp,type:ty,alert:0,wx:p.x,wy:p.y,wt:0,fireT:1+Math.random()*2,dead:false,deathT:0,hitF:0});}}
function dist(ax,ay,bx,by){return Math.hypot(ax-bx,ay-by);}
/* ---------- input ---------- */
const keys={};
window.addEventListener('keydown',e=>{keys[e.code]=true;
 if(e.code==='KeyR')startReload();
 if(e.code==='KeyG')throwNade();
 if(e.code==='Digit1')switchWep(0);if(e.code==='Digit2')switchWep(1);if(e.code==='Digit3')switchWep(2);
 if(e.code==='KeyU')popUAV();if(e.code==='KeyT')callStrike();
 if(e.code==='KeyE')interact();
 if(e.code==='KeyP'||e.code==='Escape')togglePause();
 if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();});
window.addEventListener('keyup',e=>{keys[e.code]=false;});
let locked=false;
cv.addEventListener('click',()=>{if(G.mode==='play'&&!isTouch){cv.requestPointerLock&&cv.requestPointerLock();}});
document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===cv;});
document.addEventListener('mousemove',e=>{if(locked&&G.mode==='play'&&G.alive){G.pa+=(e.movementX||0)*0.0026*set.sens;}});
cv.addEventListener('mousedown',e=>{if(G.mode!=='play')return;if(e.button===0)G.firing=true;if(e.button===2)G.ads=true;});
window.addEventListener('mouseup',e=>{if(e.button===0)G.firing=false;if(e.button===2)G.ads=false;});
cv.addEventListener('contextmenu',e=>e.preventDefault());
/* touch */
const isTouch=('ontouchstart'in window);let joyL={x:0,y:0},joyR={x:0,y:0};
function stick(el,nub,cb){let id=null;const r=()=>el.getBoundingClientRect();
 el.addEventListener('touchstart',e=>{id=e.changedTouches[0].identifier;},{passive:true});
 el.addEventListener('touchmove',e=>{for(const t of e.changedTouches){if(t.identifier===id){const b=r();let dx=(t.clientX-(b.left+60))/50,dy=(t.clientY-(b.top+60))/50;const m=Math.hypot(dx,dy)||1;dx/=Math.max(1,m);dy/=Math.max(1,m);nub.style.left=(35+dx*32)+'px';nub.style.top=(35+dy*32)+'px';cb(dx,dy);}}e.preventDefault();},{passive:false});
 const end=e=>{for(const t of e.changedTouches){if(t.identifier===id){id=null;nub.style.left='35px';nub.style.top='35px';cb(0,0);}}};
 el.addEventListener('touchend',end);el.addEventListener('touchcancel',end);}
if(isTouch){$('touch').style.display='block';stick($('stickL'),$('nubL'),(x,y)=>joyL={x,y});stick($('stickR'),$('nubR'),(x,y)=>{joyR={x,y};if(Math.abs(x)>.15&&G.mode==='play')G.pa+=x*.09*set.sens;});
 const hold=(id,down,up)=>{const el=$(id);el.addEventListener('touchstart',e=>{down();e.preventDefault();},{passive:false});el.addEventListener('touchend',e=>{if(up)up();e.preventDefault();});};
 hold('tbFire',()=>G.firing=true,()=>G.firing=false);hold('tbADS',()=>G.ads=true,()=>G.ads=false);
 hold('tbRel',()=>startReload());hold('tbNade',()=>throwNade());hold('tbWep',()=>switchWep((G.wi+1)%3));hold('tbPause',()=>togglePause());}
function switchWep(i){const w=G.weapons[i];if(!w)return;if(w.cfg.locked&&!save.unlocks.dmr){toast('LR-12 DMR UNLOCKS AT RANK 2');SFX.dry();return;}if(G.reloadT>0)return;G.wi=i;G.firing=false;SFX.click();updateTrack();}
function startReload(){const w=G.weapons[G.wi];if(G.reloadT>0||w.mag===w.cfg.mag||w.res<=0||!G.alive)return;G.reloadT=w.cfg.reload;SFX.reload();}
function throwNade(){if(G.frags<=0||!G.alive||G.mode!=='play'){if(G.frags<=0)SFX.dry();return;}G.frags--;const dx=Math.cos(G.pa),dy=Math.sin(G.pa);G.nades.push({x:G.px,y:G.py,vx:dx*7,vy:dy*7,t:0,fuse:1.1});SFX.click();say('YOU','Frag out!');}
function popUAV(){if(G.uav<=0){toast('NO UAV — STREAK AT 4 KILLS');SFX.dry();return;}if(G.uavT>0)return;G.uav--;G.uavT=25;toast('UAV ONLINE — ENEMIES REVEALED');SFX.obj();}
function callStrike(){if(G.strike<=0){toast('NO AIRSTRIKE — STREAK AT 6 KILLS');SFX.dry();return;}G.strike--;const sx=G.px+Math.cos(G.pa)*5,sy=G.py+Math.sin(G.pa)*5;G.strikes.push({x:sx,y:sy,t:1.2});say('HQ','Strike inbound. Danger close.');SFX.obj();}
function interact(){if(!G.alive||G.mode!=='play')return;const m=G.map;
 for(const it of m.items){if(!it.taken&&dist(G.px,G.py,it.x,it.y)<1.2){it.taken=true;G.intel++;G.score+=250;addXP(150);SFX.pick();feed('INTEL SECURED ('+G.intel+')');say('HQ','Intel secured. '+(MISSION_INTEL()-G.intel)+' remaining.');checkObj();return;}}
 if(G.exfilOn&&dist(G.px,G.py,m.exfil.x,m.exfil.y)<1.4){winMission('Exfiltrated with objectives complete.');}}
function MISSION_INTEL(){return G.endless?0:MISSIONS[G.mi].intel;}
/* ---------- HUD helpers ---------- */
function feed(t){const f=$('feed');const d=document.createElement('div');d.textContent=t;f.prepend(d);while(f.children.length>5)f.lastChild.remove();setTimeout(()=>{if(d.parentNode)d.style.opacity='.4';},4000);}
function say(who,t){if(set.sub){const s=$('subtitle');s.innerHTML='<span>'+who+': '+t+'</span>';G.subT=4;}}
function toast(t){const el=$('toast');el.innerHTML='<span>'+t+'</span>';clearTimeout(el._tm);el._tm=setTimeout(()=>el.innerHTML='',2600);}
function updateTrack(){const M=G.endless?{name:'ENDLESS — HOLD THE LINE',brief:'Survive. Streaks enabled.'}:MISSIONS[G.mi];
 $('mtitle').textContent=G.endless?'ENDLESS MODE':M.name;
 let o='';if(G.endless)o='Kills '+G.kills+' · Wave pressure rising';
 else if(G.mi===0)o='Eliminate hostiles — '+G.kills+'/'+MISSIONS[0].killTarget;
 else if(G.mi===1)o='Intel '+G.intel+'/'+MISSIONS[1].intel+(G.exfilOn?' — REACH ★ EXFIL':'');
 else o='Wave '+G.wave+'/3 — total kills '+G.kills+'/'+MISSIONS[2].killTarget;
 $('mobj').textContent=o;
 $('kills').textContent=G.kills;$('score').textContent=G.score;
 $('uavc').textContent=G.uav;$('stc').textContent=G.strike;
 const w=G.weapons[G.wi];$('wname').textContent=w.cfg.name+(w.cfg.locked&&!save.unlocks.dmr?' (LOCKED)':'');
 $('hptext').textContent=Math.max(0,Math.ceil(G.hp))+' HP';
 $('healthfill').style.width=Math.max(0,G.hp)+'%';
 $('eqline').childNodes[0].textContent='FRAG '+'⬤'.repeat(G.frags)+'○'.repeat(Math.max(0,2-G.frags))+' · UAV ';}
function addXP(n){save.xp+=n;const r=rankFromXP(save.xp);if(r>save.rank){save.rank=r;save.unlocks.dmr=true;toast('PROMOTED — RANK '+r+' · DMR UNLOCKED');SFX.obj();}persist();refreshRank();}
/* ---------- combat ---------- */
function los(ax,ay,bx,by){const m=G.map.g;const d=dist(ax,ay,bx,by);const n=Math.ceil(d*8);for(let i=1;i<n;i++){const t=i/n;if(m[Math.floor(ay+(by-ay)*t)][Math.floor(ax+(bx-ax)*t)]===1)return false;}return true;}
function cast(x,y,ang,maxD){const m=G.map;const dx=Math.cos(ang),dy=Math.sin(ang);let d=0;const step=.05;while(d<maxD){d+=step;const nx=x+dx*d,ny=y+dy*d;if(nx<0||ny<0||nx>=m.w||ny>=m.h)return{d,hit:1,side:0};if(m.g[Math.floor(ny)][Math.floor(nx)]===1)return{d,hit:1,side:0};}return{d:maxD,hit:0,side:0};}
function shoot(){const w=G.weapons[G.wi];if(G.reloadT>0||!G.alive)return;
 if(w.mag<=0){SFX.dry();startReload();return;}
 const now=G.t;if(now-G.triggerT<60/w.cfg.rpm)return;
 if(!w.cfg.auto&&G._semi){return;}
 G._semi=true;G.triggerT=now;w.mag--;
 const sp=(G.ads?w.cfg.adsSpread:w.cfg.spread)+G.spreadB;
 const ang=G.pa+(Math.random()-.5)*2*sp;
 const range=w.cfg.range;
 /* find enemy hit */
 let best=null,bd=range;
 for(const e of G.enemies){if(e.dead)continue;const dx=e.x-G.px,dy=e.y-G.py;const dd=Math.hypot(dx,dy);if(dd>range)continue;
  let da=Math.atan2(dy,dx)-ang;while(da>Math.PI)da-=2*Math.PI;while(da<-Math.PI)da+=2*Math.PI;
  if(Math.abs(da)<Math.max(.035,.09/dd)){if(!los(G.px,G.py,e.x,e.y))continue;if(dd<bd){bd=dd;best=e;}}}
 G.spreadB=Math.min(.05,G.spreadB+w.cfg.kick);G.shake=Math.min(6,G.shake+(G.ads?1:2.5));
 G.tracers.push({a:ang,d:best?bd:range,t:.07});
 SFX.shot(w.cfg.id);muzzle=6;
 if(best){let dmg=w.cfg.dmg*(G.ads?1.15:1)*(bd<3?1.25:1);best.hp-=dmg;best.hitF=4;best.alert=6;
  spawnBlood(best.x,best.y);
  if(best.hp<=0)killEnemy(best);else{SFX.hit();hitmarker(false);}}
 updateTrack();}
function killEnemy(e){e.dead=true;e.deathT=.6;G.kills++;G.killStreak++;G.score+=100+(e.type*25);addXP(100);
 hitmarker(true);SFX.kill();feed('HOSTILE DOWN · +100');
 if(G.killStreak===4){G.uav++;toast('KILLSTREAK — UAV READY (U)');SFX.obj();}
 if(G.killStreak===6){G.strike++;toast('KILLSTREAK — AIRSTRIKE READY (T)');SFX.obj();}
 checkObj();updateTrack();}
function hitmarker(kill){const h=$('hitmark');h.className=kill?'kill':'';h.style.opacity=1;clearTimeout(h._t);h._t=setTimeout(()=>h.style.opacity=0,120);}
function spawnBlood(x,y){for(let i=0;i<10;i++)G.parts.push({x,y,vx:(Math.random()-.5)*3,vy:(Math.random()-.5)*3,t:.4,c:'#a00'});}
function hurtPlayer(dmg,fromX,fromY){if(!G.alive||G.mode!=='play')return;G.hp-=dmg;G.lastHurt=G.t;SFX.hurt();G.shake=Math.min(9,G.shake+3);
 const ang=Math.atan2(fromY-G.py,fromX-G.px)-G.pa;showDir(ang);
 if(G.hp<=0){G.hp=0;G.alive=false;failMission('KIA — you went down in the fight.');}updateTrack();}
function showDir(ang){const s=$('dmgdir');s.innerHTML='<g transform="translate(60,60) rotate('+(ang*180/Math.PI+90)+')"><polygon points="0,-52 12,-30 -12,-30" fill="rgba(255,40,40,.9)"/></g>';clearTimeout(s._t);s._t=setTimeout(()=>s.innerHTML='',800);}
function checkObj(){if(G.endless)return;
 if(G.mi===0&&G.kills>=MISSIONS[0].killTarget)winMission('District cleared. All hostiles eliminated.');
 if(G.mi===1){if(G.intel>=MISSIONS[1].intel&&!G.exfilOn){G.exfilOn=true;toast('ALL INTEL — REACH ★ EXFIL');say('HQ','All intel secured. Get to exfil, operator.');SFX.obj();}
  if(G.exfilOn&&dist(G.px,G.py,G.map.exfil.x,G.map.exfil.y)<1.4)winMission('Intel delivered. Exfil complete.');}
 if(G.mi===2){if(G.wave<3&&G.kills>=G.wave*5){G.wave++;toast('WAVE '+G.wave+' INBOUND');say('HQ','Wave '+G.wave+' inbound. Hold the line.');spawnWave(5,[0,1,1,2,0]);SFX.obj();}
  if(G.kills>=MISSIONS[2].killTarget)winMission('Last Stand held. Enemy assault broken.');}
 updateTrack();}
function winMission(why){if(G.mode!=='play')return;G.mode='end';const time=((performance.now()-G.started)/1000).toFixed(1);
 const bonus=Math.max(0,Math.round(G.hp*5))+G.intel*250;G.score+=bonus+1000;addXP(500+Math.round(G.score/10));
 save.best=Math.max(save.best,G.score);save.completed++;persist();refreshRank();
 document.exitPointerLock&&document.exitPointerLock();G.firing=false;
 $('endKick').textContent='MISSION DEBRIEF — SUCCESS';$('endTitle').textContent='MISSION COMPLETE';
 $('endBody').textContent=why+' Intel '+G.intel+'.';
 $('endStats').textContent='KILLS '+G.kills+' · SCORE '+G.score+' · TIME '+time+'s · HP '+Math.ceil(G.hp)+' · +XP banked (Rank '+save.rank+')';
 $('btnNext').style.display=(G.mi<2&&!G.endless)?'':'none';
 $('scrEnd').classList.remove('hidden');SFX.obj();setTimeout(()=>SFX.obj(),400);}
function failMission(why){if(G.mode!=='play')return;G.mode='end';document.exitPointerLock&&document.exitPointerLock();G.firing=false;
 addXP(Math.round(G.score/20));$('endKick').textContent='MISSION DEBRIEF — FAILED';$('endTitle').textContent='MISSION FAILED';
 $('endBody').textContent=why+' Kills '+G.kills+', score '+G.score+'. Health regenerates out of fire — use cover.';
 $('endStats').textContent='TIP: ADS for accuracy · frag clusters (G) · UAV at 4-streak · retry keeps your XP.';
 $('btnNext').style.display='none';$('scrEnd').classList.remove('hidden');SFX.kill();}
function togglePause(){if(G.mode==='play'){G.mode='pause';$('scrPause').classList.remove('hidden');document.exitPointerLock&&document.exitPointerLock();}
 else if(G.mode==='pause'){G.mode='play';$('scrPause').classList.add('hidden');}}
/* ---------- update ---------- */
let muzzle=0;
function update(dt){G.t+=dt;
 if(G.mode!=='play')return;
 /* regen (CoD-style) */
 if(G.t-G.lastHurt>4&&G.hp<100&&G.alive){G.hp=Math.min(100,G.hp+22*dt);}
 if(G.subT>0){G.subT-=dt;if(G.subT<=0)$('subtitle').innerHTML='';}
 if(G.uavT>0)G.uavT-=dt;
 G.spreadB=Math.max(0,G.spreadB-dt*.06);G.shake=Math.max(0,G.shake-dt*14);if(muzzle>0)muzzle--;
 /* movement */
 const w=G.weapons[G.wi];const adsM=G.ads?.55:1;let sp=(keys['ShiftLeft']||keys['ShiftRight']?4.4:2.8)*adsM;
 if(isTouch)sp=3.2*adsM;
 let mx=0,my=0;
 if(keys['KeyW']||keys['ArrowUp'])my+=1;if(keys['KeyS']||keys['ArrowDown'])my-=1;if(keys['KeyA'])mx-=1;if(keys['KeyD'])mx+=1;
 mx+=joyL.x;my-=joyL.y;
 const mlen=Math.hypot(mx,my);if(mlen>1){mx/=mlen;my/=mlen;}
 const ca=Math.cos(G.pa),sa=Math.sin(G.pa);
 const nx=G.px+(ca*my-sa*mx)*sp*dt,ny=G.py+(sa*my+ca*mx)*sp*dt;
 const gm=G.map.g;
 if(gm[Math.floor(G.py)][Math.floor(nx)]===0)G.px=nx;
 if(gm[Math.floor(nx?G.px:G.px)][Math.floor(ny)]===0||gm[Math.floor(G.py)][Math.floor(G.px)]===0){if(gm[Math.floor(G.py)][Math.floor(ny)]===0)G.py=ny;}
 /* reload */
 if(G.reloadT>0){G.reloadT-=dt;if(G.reloadT<=0){const need=w.cfg.mag-w.mag,take=Math.min(need,w.res);w.mag+=take;w.res-=take;}}
 $('reloadprompt').style.display=(w.mag<=Math.ceil(w.cfg.mag*.25))?'block':'none';
 if(G.firing&&G.alive)shoot();if(!G.firing)G._semi=false;
 /* grenades */
 for(let i=G.nades.length-1;i>=0;i--){const n=G.nades[i];n.t+=dt;n.x+=n.vx*dt;n.y+=n.vy*dt;n.vx*=.98;n.vy*=.98;
  if(gm[Math.floor(n.y)]&&gm[Math.floor(n.y)][Math.floor(n.x)]===1){n.vx*=-.5;n.vy*=-.5;n.x+=n.vx*dt*2;n.y+=n.vy*dt*2;}
  if(n.t>=n.fuse){G.nades.splice(i,1);explode(n.x,n.y,4.5,160);}}
 /* airstrikes */
 for(let i=G.strikes.length-1;i>=0;i--){const s=G.strikes[i];s.t-=dt;if(s.t<=0){G.strikes.splice(i,1);explode(s.x,s.y,5.5,300);explode(s.x+1.5,s.y-1,4,200);}}
 /* enemies AI */
 const diff=G.endless?1+G.kills*.02:(G.mi===2?1.1:1);
 for(const e of G.enemies){if(e.dead){e.deathT-=dt;continue;}
  if(e.hitF>0)e.hitF--;
  const d=dist(G.px,G.py,e.x,e.y);const seen=d<(G.uavT>0?99:11)&&los(e.x,e.y,G.px,G.py);
  if(seen)e.alert=6;else if(e.alert>0)e.alert-=dt;
  /* move */
  e.wt-=dt;
  if(e.alert>0&&d>2.2){const a=Math.atan2(G.py-e.y,G.px-e.x)+(e.type===1?Math.sin(G.t*2)*.3:0);const es=(e.type===1?2.4:1.5)*diff*dt;
   const tx=e.x+Math.cos(a)*es,ty=e.y+Math.sin(a)*es;
   if(gm[Math.floor(e.y)][Math.floor(tx)]===0)e.x=tx;if(gm[Math.floor(ty)]&&gm[Math.floor(ty)][Math.floor(e.x)]===0)e.y=ty;}
  else if(e.alert<=0){if(e.wt<=0){e.wt=2+Math.random()*3;const p=randFree();e.wx=p.x;e.wy=p.y;}
   const a=Math.atan2(e.wy-e.y,e.wx-e.x);const es=.8*dt;const tx=e.x+Math.cos(a)*es,ty=e.y+Math.sin(a)*es;
   if(gm[Math.floor(e.y)][Math.floor(tx)]===0)e.x=tx;if(gm[Math.floor(ty)]&&gm[Math.floor(ty)][Math.floor(e.x)]===0)e.y=ty;}
  /* attack */
  e.fireT-=dt;
  if(seen&&e.fireT<=0&&G.alive){e.fireT=(e.type===2?1.6:(e.type===1?.9:1.3))/diff;
   const acc=e.type===2?.09:(e.type===1?.16:.12);const aimErr=(Math.random()-.5)*2*acc+d*.008;
   const aimA=Math.atan2(G.py-e.y,G.px-e.x)+aimErr;
   const r=cast(e.x,e.y,aimA,d+1);
   G.tracers.push({ex:e.x,ey:e.y,a:aimA,d:Math.min(d,r.d),t:.09,foe:true});
   noise(.08,.12,1800);
   if(r.d>=d-.3){hurtPlayer((e.type===2?26:(e.type===1?9:13))*diff,e.x,e.y);}}}
 /* endless scaling */
 if(G.endless&&G.enemies.filter(e=>!e.dead).length<3){spawnWave(3,[0,1,2]);toast('HOSTILE REINFORCEMENTS');}
 /* particles/tracers decay */
 for(let i=G.parts.length-1;i>=0;i--){const p=G.parts[i];p.t-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.t<=0)G.parts.splice(i,1);}
 for(let i=G.tracers.length-1;i>=0;i--){G.tracers[i].t-=dt;if(G.tracers[i].t<=0)G.tracers.splice(i,1);}
 /* M2 passive exfil check + touch exfil prompt */
 if(G.mi===1&&G.exfilOn&&dist(G.px,G.py,G.map.exfil.x,G.map.exfil.y)<1.4&&G.alive)interact();
 $('dmgvin').style.opacity=set.reduceFlash?Math.min(.4,(100-G.hp)/140):Math.min(.95,(100-G.hp)/110);
 updateTrack();}
function explode(x,y,rad,dmg){SFX.boom();G.shake=9;
 for(let i=0;i<26;i++)G.parts.push({x,y,vx:(Math.random()-.5)*9,vy:(Math.random()-.5)*9,t:.7,c:Math.random()<.5?'#fa0':'#555'});
 for(const e of G.enemies){if(e.dead)continue;const d=dist(x,y,e.x,e.y);if(d<rad){e.hp-=(1-d/rad)*dmg+40;e.alert=6;e.hitF=4;if(e.hp<=0)killEnemy(e);else{SFX.hit();}}}
 if(dist(x,y,G.px,G.py)<rad*.7)hurtPlayer(35,x,y);}
/* ---------- render (raycast walls + billboard sprites + gun) ---------- */
function render(){ctx.fillStyle='#0a0d12';ctx.fillRect(0,0,W,H);
 if(G.mode==='brief'||!G.map){menuBackdrop();return;}
 const w=G.weapons[G.wi];const zoom=G.ads?w.cfg.zoom:1;
 const fov=(Math.PI/3)/zoom;const num=Math.floor(W/3);
 const shakeX=(Math.random()-.5)*G.shake,shakeY=(Math.random()-.5)*G.shake;
 for(let i=0;i<num;i++){const ra=G.pa-fov/2+fov*i/num;const r=cast(G.px,G.py,ra,24);
  const corr=r.d*Math.cos(ra-G.pa);const wallH=Math.min(H*3,(H*.9/Math.max(.15,corr))*zoom);
  const shade=Math.max(.25,1-corr/22);const side=(((ra*10)%2)+2)%2>1?.92:1;
  const base=(60+corr*8)%60;
  ctx.fillStyle='rgb('+Math.floor((70+base)*shade*side)+','+Math.floor((72+base*.8)*shade*side)+','+Math.floor((80+base*.6)*shade*side)+')';
  const y0=H/2-wallH/2+shakeY;
  ctx.fillRect(i*3+shakeX,y0,3,wallH);
  ctx.fillStyle='rgba(0,0,0,.25)';ctx.fillRect(i*3+shakeX,y0,3,wallH*.12);}
 /* floor/ceiling gradient */
 /* sprites: items, exfil, enemies, grenades (painter's algorithm) */
 const spr=[];
 for(const it of G.map.items)if(!it.taken)spr.push({d:dist(G.px,G.py,it.x,it.y),k:'intel',x:it.x,y:it.y});
 if(G.exfilOn||G.mi!==1)spr.push({d:dist(G.px,G.py,G.map.exfil.x,G.map.exfil.y),k:'exfil',x:G.map.exfil.x,y:G.map.exfil.y});
 for(const e of G.enemies)if(!(e.dead&&e.deathT<=0))spr.push({d:dist(G.px,G.py,e.x,e.y),k:'foe',e});
 for(const n of G.nades)spr.push({d:dist(G.px,G.py,n.x,n.y),k:'nade',x:n.x,y:n.y});
 spr.sort((a,b)=>b.d-a.d);
 for(const s of spr){let da=0,size=0;
  if(s.k==='foe'){da=Math.atan2(s.e.y-G.py,s.e.x-G.px)-G.pa;}
  else{da=Math.atan2(s.y-G.py,s.x-G.px)-G.pa;}
  while(da>Math.PI)da-=2*Math.PI;while(da<-Math.PI)da+=2*Math.PI;
  if(Math.abs(da)>fov/2+.3)continue;
  const r=cast(G.px,G.py,G.pa+da,s.d);
  if(r.d<s.d-.4)continue;
  const sx=(0.5+da/fov)*W+shakeX;size=Math.min(H*1.4,(H*.75/Math.max(.3,s.d))*zoom);
  if(s.k==='foe')drawSoldier(sx,H/2+size*.08+shakeY,size,s.e);
  else if(s.k==='intel'){ctx.fillStyle='#e8b64c';ctx.fillRect(sx-size*.12,H/2-size*.1,size*.24,size*.2);ctx.fillStyle='#111';ctx.font=Math.floor(size*.14)+'px monospace';ctx.textAlign='center';ctx.fillText('INTEL',sx,H/2+size*.06);}
  else if(s.k==='exfil'){ctx.fillStyle=G.exfilOn||G.mi!==1?'#7dff9a':'#556';ctx.font='bold '+Math.floor(size*.3)+'px monospace';ctx.textAlign='center';ctx.fillText('★',sx,H/2);ctx.font=Math.floor(size*.1)+'px monospace';ctx.fillText(G.mi===1&&!G.exfilOn?'LOCKED':'EXFIL',sx,H/2+size*.2);}
  else if(s.k==='nade'){ctx.fillStyle='#0f0';ctx.beginPath();ctx.arc(sx,H/2+size*.1,size*.03,0,7);ctx.fill();}}
 /* tracers */
 ctx.strokeStyle='rgba(255,230,150,.85)';ctx.lineWidth=2;
 for(const t of G.tracers){const ox=W/2,oy=H/2;const off=(t.a-G.pa)/(fov/2)*(W/2);
  ctx.beginPath();ctx.moveTo(ox+off*.2,oy+40);ctx.lineTo(ox+off,oy-20);ctx.stroke();}
 /* gun */
 drawGun(w);
 /* UAV reveal ring pulse + scope overlay */
 if(G.ads&&w.cfg.id===2){ctx.strokeStyle='rgba(0,0,0,.9)';ctx.lineWidth=Math.max(20,W*.06);ctx.beginPath();ctx.arc(W/2,H/2,Math.min(W,H)*.42,0,7);ctx.stroke();ctx.fillStyle='rgba(0,0,0,.25)';ctx.fillRect(0,0,W,H);}
 if(G.uavT>0){ctx.fillStyle='rgba(0,229,255,.08)';ctx.fillRect(0,0,W,H);}
 /* low-hp heartbeat */
 if(G.hp<35&&G.alive&&Math.floor(G.t*1.4)%2===0&&!set.mute){/* visual pulse */ctx.fillStyle='rgba(180,0,0,.12)';ctx.fillRect(0,0,W,H);}
 drawMinimap();drawCompass();}
function drawSoldier(sx,sy,size,e){const h=size,hw=size*.22;
 if(e.dead){ctx.save();ctx.translate(sx,sy);ctx.rotate(Math.PI/2);ctx.fillStyle='#3a2a2a';ctx.fillRect(-hw,-h*.1,hw*2,h*.12);ctx.restore();return;}
 const flash=e.hitF>0;
 const uni=e.type===2?'#4a3f35':(e.type===1?'#5a2f2f':'#3d4a3d');
 ctx.fillStyle=flash?'#fff':uni;ctx.fillRect(sx-hw,sy-h,hw*2,h*.62);
 ctx.fillStyle=flash?'#fff':'#c9a07a';ctx.beginPath();ctx.arc(sx,sy-h*.72,hw*.55,0,7);ctx.fill();
 ctx.fillStyle='#222';ctx.fillRect(sx-hw*.7,sy-h*.86,hw*1.4,hw*.4);
 ctx.fillStyle='#111';ctx.fillRect(sx-hw*.15,sy-h*.5,hw*.3,h*.3);
 if(e.type===2){ctx.fillStyle='#000';ctx.fillRect(sx+hw*.2,sy-h*.45,hw*1.1,hw*.18);}
 /* hp pip */
 ctx.fillStyle='rgba(0,0,0,.6)';ctx.fillRect(sx-hw,sy-h-8,hw*2,4);
 ctx.fillStyle=e.hp/e.maxhp>.5?'#7dff9a':'#ff4d4d';ctx.fillRect(sx-hw,sy-h-8,hw*2*Math.max(0,e.hp/e.maxhp),4);}
let muzzle=0;
function drawGun(w){const gw=W*.34,gh=H*.2;const gx=W/2-gw/2+(G.ads?-gw*.06:0),gy=H-gh-H*.02+(G.ads?-gh*.28:0)+(Math.random()-.5)*G.shake*.6;
 ctx.save();
 ctx.fillStyle='#161a20';ctx.strokeStyle='#000';ctx.lineWidth=2;
 ctx.beginPath();ctx.rect(gx+gw*.3,gy,gw*.4,gh*.7);ctx.fill();ctx.stroke();
 ctx.fillStyle='#232a35';ctx.fillRect(gx+gw*.42,gy-gh*.5+(G.ads?-gh*.25:0),gw*.16,gh*.6);
 ctx.fillStyle='#0d0f13';ctx.fillRect(gx+gw*.1,gy+gh*.55,gw*.8,gh*.16);
 if(w.cfg.id===1){ctx.fillStyle='#2c3646';ctx.fillRect(gx+gw*.3,gy-gh*.2,gw*.4,gh*.3);}
 if(w.cfg.id===2){ctx.fillStyle='#10141a';ctx.fillRect(gx+gw*.44,gy-gh*.75,gw*.12,gh*.4);ctx.beginPath();ctx.arc(gx+gw*.5,gy-gh*.6,gw*.09,0,7);ctx.strokeStyle='#000';ctx.stroke();}
 /* ammo readout on gun + ads reticle */
 ctx.fillStyle='#e8b64c';ctx.font=Math.floor(H*.022)+'px monospace';ctx.textAlign='center';
 ctx.fillText(w.mag+' / '+w.res,gx+gw*.5,gy+gh*.62);
 if(muzzle>0){ctx.fillStyle='rgba(255,200,80,.9)';ctx.beginPath();ctx.arc(gx+gw*.5,gy-gh*.5,10+Math.random()*10,0,7);ctx.fill();}
 if(G.ads&&w.cfg.id!==2){ctx.strokeStyle='rgba(255,255,255,.85)';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(W/2,H/2,14,0,7);ctx.stroke();}
 if(G.reloadT>0){ctx.fillStyle='#fff';ctx.font='bold '+Math.floor(H*.03)+'px monospace';ctx.fillText('RELOADING…',W/2,H*.72);}
 ctx.restore();
 /* crosshair spread */
 const c=$('cross');const s=G.ads?.5:(1+G.spreadB*14);c.style.transform='translate(-50%,-50%) scale('+s.toFixed(2)+')';c.style.opacity=G.ads&&w.cfg.id===2?0:1;}
function drawCompass(){const el=$('compasstrip');const deg=((G.pa*180/Math.PI)%360+360)%360;
 let html='';for(let d=-120;d<=120;d+=15){const a=Math.round((deg+d)/15)*15;const norm=((a%360)+360)%360;
  const names={0:'N',45:'NE',90:'E',135:'SE',180:'S',225:'SW',270:'W',315:'NW'};
  const lab=names[norm]!==undefined?names[norm]:norm;
  const cls=norm===Math.round(deg/15)*15%360?'deg':'';
  html+='<span class="'+cls+'" style="display:inline-block;width:44px;text-align:center">'+lab+'</span>';}
 /* objective star */
 el.innerHTML=html;el.style.left='calc(50% - '+(el.scrollWidth/2)+'px)';
 /* exfil/objective marker: simple edge indicator via toast-free arrow */
 }
function drawMinimap(){const s=150,c=mmc;m=s/2;mmc.clearRect(0,0,s,s);
 mmc.fillStyle='rgba(10,14,20,.9)';mmc.beginPath();mmc.arc(c,c,74,0,7);mmc.fill();
 const m=G.map;const sc=s/Math.max(m.w,m.h);
 mmc.fillStyle='#2c3a4e';
 for(let y=0;y<m.h;y++)for(let x=0;x<m.w;x++)if(m.g[y][x]===1)mmc.fillRect(x*sc,y*sc,Math.ceil(sc),Math.ceil(sc));
 const px=x=>(x)*sc,py=y=>(y)*sc;
 mmc.fillStyle='#e8b64c';for(const it of m.items)if(!it.taken){mmc.fillRect(px(it.x)-2,py(it.y)-2,4,4);}
 mmc.fillStyle='#7dff9a';mmc.font='bold 12px monospace';mmc.fillText('★',px(m.exfil.x)-4,py(m.exfil.y)+4);
 const showAll=G.uavT>0;
 mmc.fillStyle='#ff5b5b';for(const e of G.enemies){if(e.dead)continue;const d=dist(G.px,G.py,e.x,e.y);if(showAll||d<8){mmc.beginPath();mmc.arc(px(e.x),py(e.y),3,0,7);mmc.fill();}}
 /* player wedge */
 mmc.save();mmc.translate(px(G.px),py(G.py));mmc.rotate(Math.atan2(Math.sin(G.pa),Math.cos(G.pa)));mmc.fillStyle='#fff';mmc.beginPath();mmc.moveTo(7,0);mmc.lineTo(-4,-5);mmc.lineTo(-4,5);mmc.closePath();mmc.fill();mmc.restore();}
function menuBackdrop(){ctx.fillStyle='#0d1420';ctx.fillRect(0,0,W,H);ctx.fillStyle='rgba(232,182,76,.06)';for(let i=0;i<40;i++){ctx.fillRect((i*97)%W,(i*61)%H,2,2);}}
/* ---------- main loop ---------- */
let last=performance.now();
function loop(now){let dt=(now-last)/1000;last=now;dt=Math.min(.05,dt);
 try{update(dt);render();}catch(e){errBox.style.display='block';errBox.textContent='Frame recovered: '+(e.message||e);}
 requestAnimationFrame(loop);}
/* ---------- wiring ---------- */
$('btnDeploy').onclick=()=>{SFX.click();ac();startMission(0,false);};
$('btnEndless').onclick=()=>{SFX.click();ac();startMission(0,true);};
$('btnHow').onclick=()=>{toast('RANK '+save.rank+' · '+save.xp+' XP · BEST '+save.best+' · COMPLETED x'+save.completed);};
$('btnResume').onclick=()=>togglePause();
$('btnRestart').onclick=()=>{startMission(G.mi,G.endless);};
$('btnQuit').onclick=()=>{G.mode='brief';$('scrPause').classList.add('hidden');$('scrBrief').classList.remove('hidden');};
$('btnRetry').onclick=()=>startMission(G.mi,G.endless);
$('btnBrief').onclick=()=>{G.mode='brief';$('scrEnd').classList.add('hidden');$('scrBrief').classList.remove('hidden');};
$('btnNext').onclick=()=>startMission(Math.min(2,G.mi+1),false);
setInterval(()=>{if(G.mode==='play'&&G.alive){/* heartbeat sfx at low hp */if(G.hp<35)SFX.heart();}},1100);
window.addEventListener('pointerlockerror',()=>{toast('CLICK BATTLEFIELD TO CAPTURE MOUSE');});
applyCB();fit();updateTrack();requestAnimationFrame(loop);
/* expose for headless smoke test */
window.__SP={G,startMission,shoot,switchWep,save};
</script>
