const puppeteer = require('puppeteer-core');
const SHOT = '/tmp/sp_shots';
(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--window-size=1280,720', '--hide-scrollbars']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 720 });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('file:///Users/runner/work/PlayGround/PlayGround/game/index.html', { waitUntil: 'load' });
  await new Promise(r => setTimeout(r, 800));
  await page.screenshot({ path: SHOT + '/1_brief.png' });
  await page.click('#btnDeploy');
  await page.waitForFunction(() => window.__SP && window.__SP.G.mode === 'play', { timeout: 5000 });
  await new Promise(r => setTimeout(r, 1200));
  await page.screenshot({ path: SHOT + '/2_spawn.png' });
  // Aim at nearest live enemy and fire
  const aim = await page.evaluate(() => {
    const { G } = window.__SP;
    let best = null, bd = 1e9;
    for (const e of G.enemies) { if (e.dead) continue; const d = Math.hypot(e.x - G.px, e.y - G.py); if (d < bd) { bd = d; best = e; } }
    if (!best) return null;
    G.pa = Math.atan2(best.y - G.py, best.x - G.px);
    return { d: bd.toFixed(2), hp: G.hp, foes: G.enemies.filter(e => !e.dead).length };
  });
  await page.evaluate(() => { window.__SP.G.firing = true; });
  await new Promise(r => setTimeout(r, 2500));
  await page.evaluate(() => { window.__SP.G.firing = false; });
  const afterFire = await page.evaluate(() => ({ kills: window.__SP.G.kills, score: window.__SP.G.score, hp: Math.round(window.__SP.G.hp), mag: window.__SP.G.weapons[window.__SP.G.wi].mag }));
  await page.screenshot({ path: SHOT + '/3_combat.png' });
  // ADS view
  await page.evaluate(() => { window.__SP.G.ads = true; });
  await new Promise(r => setTimeout(r, 600));
  await page.screenshot({ path: SHOT + '/4_ads.png' });
  await page.evaluate(() => { window.__SP.G.ads = false; });
  // Move forward + grenade
  await page.keyboard.down('KeyW');
  await page.evaluate(() => { window.__SP.G.frags = 2; });
  await page.keyboard.press('KeyG');
  await new Promise(r => setTimeout(r, 1600));
  await page.keyboard.up('KeyW');
  await page.screenshot({ path: SHOT + '/5_nade.png' });
  const mid = await page.evaluate(() => ({ px: window.__SP.G.px.toFixed(2), py: window.__SP.G.py.toFixed(2), hp: Math.round(window.__SP.G.hp), kills: window.__SP.G.kills }));
  // Pause
  await page.keyboard.press('KeyP');
  await new Promise(r => setTimeout(r, 400));
  const pausedMode = await page.evaluate(() => window.__SP.G.mode);
  await page.screenshot({ path: SHOT + '/6_pause.png' });
  await page.click('#btnResume');
  await new Promise(r => setTimeout(r, 300));
  const resumedMode = await page.evaluate(() => window.__SP.G.mode);
  // Force win path
  await page.evaluate(() => { const { G } = window.__SP; for (const e of G.enemies) { if (!e.dead) { e.hp = 1; } } });
  await page.evaluate(() => { const SP = window.__SP; const { G } = SP; for (const e of [...G.enemies]) { if (!e.dead) { e.hp = 0.01; } } G.firing = false; });
  // use real kill path: shoot remaining via killEnemy through damage is complex; call checkObj via direct kills
  await page.evaluate(() => {
    const { G } = window.__SP;
    // simulate legit kills by damaging each enemy through game code path
    for (const e of G.enemies) { if (!e.dead) { e.hp = -1; } }
  });
  await new Promise(r => setTimeout(r, 500));
  // Fail path on fresh mission instead: restart then kill player
  await page.evaluate(() => { window.__SP.startMission(0, false); });
  await new Promise(r => setTimeout(r, 600));
  await page.screenshot({ path: SHOT + '/7_restart.png' });
  const fps = await page.evaluate(() => new Promise(res => {
    let n = 0; const t0 = performance.now();
    const tick = () => { n++; if (performance.now() - t0 < 2000) requestAnimationFrame(tick); else res((n / 2).toFixed(0)); };
    requestAnimationFrame(tick);
  }));
  console.log(JSON.stringify({ aim, afterFire, mid, pausedMode, resumedMode, fps, errors }));
  await browser.close();
})().catch(e => { console.error('DRIVER_FAIL ' + e.message); process.exit(1); });

const puppeteer = require('puppeteer-core');
(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--window-size=1280,720']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 720 });
  const errs = [];
  page.on('pageerror', e => errs.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errs.push('CONSOLE: ' + m.text()); });
  await page.goto('file:///Users/runner/work/PlayGround/PlayGround/game/index.html', { waitUntil: 'load' });
  await new Promise(r => setTimeout(r, 800));
  const diag = await page.evaluate(() => ({
    hasSP: !!window.__SP, mode: window.__SP && window.__SP.G.mode,
    btn: !!document.getElementById('btnDeploy'),
    hidden: document.getElementById('scrBrief').className
  }));
  console.log('DIAG ' + JSON.stringify(diag));
  // click via JS to rule out puppeteer click issues
  await page.evaluate(() => document.getElementById('btnDeploy').click());
  await new Promise(r => setTimeout(r, 800));
  const after = await page.evaluate(() => ({ mode: window.__SP.G.mode, foes: window.__SP.G.enemies.length }));
  console.log('AFTER ' + JSON.stringify(after) + ' ERRORS ' + JSON.stringify(errs));
  await browser.close();
})().catch(e => { console.error('DRIVER_FAIL ' + e.message); process.exit(1); });

