const puppeteer = require('puppeteer-core');
const SHOT = '/tmp/sp_shots';
(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--window-size=1280,720', '--hide-scrollbars']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 720 });
  const errs = [];
  page.on('pageerror', e => errs.push('PAGEERROR: ' + e.message));
  await page.goto('file:///Users/runner/work/PlayGround/PlayGround/game/index.html', { waitUntil: 'load' });
  await new Promise(r => setTimeout(r, 500));
  await page.evaluate(() => document.getElementById('btnDeploy').click());
  await page.waitForFunction(() => window.__SP && window.__SP.G.mode === 'play', { timeout: 5000 });
  await new Promise(r => setTimeout(r, 400));
  // face nearest LOS enemy, ADS + muzzle flash frame
  await page.evaluate(() => {
    const SP = window.__SP, G = SP.G;
    let best = null, bd = 1e9;
    for (const e of G.enemies) { if (!e.dead && SP.los(G.px, G.py, e.x, e.y)) { const d = Math.hypot(e.x - G.px, e.y - G.py); if (d < bd) { bd = d; best = e; } } }
    if (best) G.pa = Math.atan2(best.y - G.py, best.x - G.px);
    G.ads = true; G.firing = true;
  });
  await new Promise(r => setTimeout(r, 350));
  await page.screenshot({ path: SHOT + '/12_ads_enemy.png' });
  await page.evaluate(() => { window.__SP.G.firing = false; window.__SP.G.ads = false; });
  // touch layout: mobile viewport with touch
  const m = await browser.newPage();
  await m.setViewport({ width: 390, height: 844, isMobile: true, hasTouch: true });
  await m.goto('file:///Users/runner/work/PlayGround/PlayGround/game/index.html', { waitUntil: 'load' });
  await new Promise(r => setTimeout(r, 500));
  await m.evaluate(() => document.getElementById('btnDeploy').click());
  await new Promise(r => setTimeout(r, 900));
  await m.screenshot({ path: SHOT + '/13_touch.png' });
  const touchVisible = await m.evaluate(() => getComputedStyle(document.getElementById('touch')).display);
  console.log(JSON.stringify({ errs, touchVisible }));
  await browser.close();
})().catch(e => { console.error('DRIVER_FAIL ' + e.message); process.exit(1); });

