+<style>
+:root{--hud-scale:1;--amber:#e8b64c;--green:#7dff9a;--red:#ff4d4d;--bg:#0b0e12}
+*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
+html,body{width:100%;height:100%;background:var(--bg);color:#e8e8e8;font-family:"Segoe UI",Roboto,Helvetica,Arial,sans-serif;overflow:hidden;user-select:none}
+#wrap{position:fixed;inset:0;display:flex;flex-direction:column}
+#gamebar{display:flex;align-items:center;gap:10px;padding:6px 12px;background:#10151c;border-bottom:1px solid #232c38;font-size:12px;letter-spacing:.08em}
+#gamebar b{color:var(--amber)} #gamebar .sp{flex:1}
+button{font-family:inherit}
+.screen{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;background:radial-gradient(ellipse at 50% 30%,#1a2230 0%,#0b0e12 70%);z-index:20;padding:20px;text-align:center}
+.screen.hidden{display:none}
+.card{max-width:640px;width:min(92vw,640px);background:rgba(16,21,28,.94);border:1px solid #2b3648;border-radius:10px;padding:26px 28px;text-align:left;box-shadow:0 20px 60px rgba(0,0,0,.6)}
+.card h1{font-size:30px;letter-spacing:.12em;color:#fff} .card h1 span{color:var(--amber)}
+.card h2{font-size:18px;letter-spacing:.1em;color:var(--amber);margin-bottom:8px}
+.card p{font-size:14px;line-height:1.55;color:#c6cfdb;margin:8px 0}
