+#compasstrip .deg{color:var(--amber);font-weight:700}
+#objstar{color:var(--amber);font-weight:900}
+#missiontrack{position:absolute;top:46px;left:12px;background:rgba(0,0,0,.5);border-left:3px solid var(--amber);padding:6px 10px;border-radius:0 5px 5px 0;max-width:300px}
+#missiontrack .t{font-size:11px;letter-spacing:.12em;color:var(--amber)} #missiontrack .o{font-size:13px;color:#fff}
