+#feed{position:absolute;top:204px;right:12px;width:230px;display:flex;flex-direction:column;gap:4px;align-items:flex-end}
+#feed div{background:rgba(0,0,0,.55);padding:3px 8px;border-radius:4px;font-size:12px}
+#bottomleft{position:absolute;left:12px;bottom:12px;background:rgba(0,0,0,.5);border:1px solid rgba(255,255,255,.12);border-radius:6px;padding:8px 12px}
+#healthbar{width:190px;height:10px;background:#2a1214;border-radius:5px;overflow:hidden;margin-top:5px}
+#healthfill{height:100%;width:100%;background:linear-gradient(90deg,#57d977,#a8e05f);transition:width .15s}
