const puppeteer = require('puppeteer-core');
const SHOT = '/Users/runner/work/PlayGround/PlayGround/screenshots';
(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--window-size=1280,720', '--hide-scrollbars']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 720 });
  const errs = [];
  page.on('pageerror', e => errs.push('PAGEERROR: ' + e.message));
  const url = await page.evaluate(() => location.href).catch(() => '');
  await page.goto('http://127.0.0.1:3000/index.html', { waitUntil: 'load', timeout: 20000 });
  const servedUrl = 'http://127.0.0.1:3000/index.html';
  await new Promise(r => setTimeout(r, 700));
  await page.screenshot({ path: SHOT + '/final-briefing.png' });
  await page.evaluate(() => document.getElementById('btnDeploy').click());
  await page.waitForFunction(() => window.__SP && window.__SP.G.mode === 'play', { timeout: 8000 });
  await new Promise(r => setTimeout(r, 900));
  await page.screenshot({ path: SHOT + '/final-spawn.png' });
  // combat: face LOS enemy, ADS burst
  await page.evaluate(() => {
    const SP = window.__SP, G = SP.G;
    let best = null, bd = 1e9;
    for (const e of G.enemies) { if (!e.dead && SP.los(G.px, G.py, e.x, e.y)) { const d = Math.hypot(e.x - G.px, e.y - G.py); if (d < bd) { bd = d; best = e; } } }
    if (best) G.pa = Math.atan2(best.y - G.py, best.x - G.px);
    G.ads = true; G.firing = true;
  });
  await new Promise(r => setTimeout(r, 2500));
  await page.screenshot({ path: SHOT + '/final-combat.png' });
  await page.evaluate(() => { window.__SP.G.firing = false; window.__SP.G.ads = false; });
  const combat = await page.evaluate(() => ({ kills: window.__SP.G.kills, score: window.__SP.G.score, hp: Math.round(window.__SP.G.hp) }));
  // pause
  await page.keyboard.press('KeyP');
  await new Promise(r => setTimeout(r, 400));
  await page.screenshot({ path: SHOT + '/final-pause.png' });
  const paused = await page.evaluate(() => window.__SP.G.mode);
  await page.click('#btnResume');
  await new Promise(r => setTimeout(r, 300));
  // win + debrief
  await page.evaluate(() => { const SP = window.__SP; for (const e of [...SP.G.enemies]) if (!e.dead) SP.killEnemy(e); });
  await new Promise(r => setTimeout(r, 600));
  await page.screenshot({ path: SHOT + '/final-debrief.png' });
  const endTitle = await page.evaluate(() => document.getElementById('endTitle').textContent);
  console.log(JSON.stringify({ servedUrl, combat, paused, endTitle, errs }));
  await browser.close();
})().catch(e => { console.error('DRIVER_FAIL ' + e.message); process.exit(1); });

